correction.en:
Benefits recap: clear, specific error messages let Claude identify the exact problem ("date format cannot be empty"), choose a corrective action, and retry with corrected parameters. To enable this, validate early, raise deterministic errors, and expose structured error text or JSON the model can parse.

Example implementation and retry pattern:

```
from datetime import datetime

def get_current_datetime(date_format="%Y%m%d %H:%M:%S"):
    if not date_format:
        # deterministic, parseable error message
        raise ValueError("date format cannot be empty")
    return datetime.now().strftime(date_format)

def call_with_retry(date_format, max_retries=1):
    attempt = 0
    while True:
        try:
            return {"success": True, "result": get_current_datetime(date_format)}
        except ValueError as e:
            attempt += 1
            msg = str(e)
            # Expose structured error to the LLM/tool caller
            error_payload = {"success": False, "error": {"code": "EMPTY_FORMAT", "message": msg}}
            # Example automated correction based on exact message
            if attempt <= max_retries and "date format cannot be empty" in msg:
                date_format = "%Y%m%d %H:%M:%S"  # corrected value
                continue
            return error_payload
```

Best practices: use concise, consistent messages and optional error codes; return structured error objects; document corrective suggestions; implement bounded retry policies and logging so Claude can safely retry with corrected inputs.

import { ToolParam } from "anthropic.types";

export const summarize_article_schema: ToolParam = {
  type: "object",
  title: "summarize_article_schema",
  description: "Summarize a web article into a compact, readable output tailored to user needs. Use the URL to fetch the article, then return a summary in the requested format and length. This tool is intended for downstream display or inclusion in reports; it should not hallucinate content not present in the source. Prefer conservative outputs when the source is ambiguous or truncated.",
  properties: {
    url: {
      type: "string",
      description: "The canonical HTTP(S) URL of the article to summarize. Provide a fully-qualified URL (including scheme) so the tool can fetch the exact resource; do not pass HTML or raw text in this field. If the article is behind authentication, note that the fetch will fail unless the tool is proxied with credentials. Use this to point the summarizer to the authoritative source."
    },
    format: {
      type: "string",
      enum: ["concise", "bullet_points", "detailed"],
      description: "Desired output style for the summary. 'concise' returns a short paragraph (1–3 sentences), 'bullet_points' returns 3–8 key bullets, and 'detailed' returns a multi-paragraph executive summary (4–8 sentences). Choose the style that best fits downstream consumption (e.g., UI card vs. report). If omitted, the tool defaults to 'concise'."
    },
    max_length: {
      type: "integer",
      minimum: 50,
      maximum: 2000,
      default: 250,
      description: "Approximate maximum token/character length for the generated summary. The tool will try to respect this limit while preserving coherent sentences. Use higher values for thorough summaries and lower values for compact displays. Values outside the range will be clamped to the min/max."
    },
    include_source_excerpt: {
      type: "boolean",
      default: false,
      description: "When true, include a short (1–2 sentence) excerpt from the article that supports the summary. This helps users verify the summary against the source and reduces hallucination risk. Only include text that the fetch returned; do not fabricate excerpts. Useful for transparency in sensitive contexts."
    }
  },
  required: ["url"],
  additionalProperties: false
};

